class Solution:
    def shortestPalindrome(self, s: str) -> str:
        rev = s[::-1]
        combo = s + '#' + rev
        n = len(combo)
        lps = [0] * n
        prev = 0
        i = 1
        while i < n:
            if combo[i] == combo[prev]:
                prev += 1
                lps[i] = prev
                i += 1
            elif prev > 0:
                prev = lps[prev - 1]
            else:
                lps[i] = 0
                i += 1
        k = lps[-1]
        return rev[:len(s) - k] + s

class Solution {
public:
    string shortestPalindrome(string s) {
        string rev = s;
        reverse(rev.begin(), rev.end());
        string combo = s + '#' + rev;
        int n = combo.size();
        vector<int> lps(n, 0);
        int prev = 0, i = 1;
        while (i < n) {
            if (combo[i] == combo[prev]) {
                lps[i++] = ++prev;
            } else if (prev > 0) {
                prev = lps[prev - 1];
            } else {
                lps[i++] = 0;
            }
        }
        int k = lps.back();
        return rev.substr(0, s.size() - k) + s;
    }
};

class Solution {
    public String shortestPalindrome(String s) {
        String rev = new StringBuilder(s).reverse().toString();
        String combo = s + "#" + rev;
        int n = combo.length();
        int[] lps = new int[n];
        int prev = 0, i = 1;
        while (i < n) {
            if (combo.charAt(i) == combo.charAt(prev)) {
                lps[i++] = ++prev;
            } else if (prev > 0) {
                prev = lps[prev - 1];
            } else {
                lps[i++] = 0;
            }
        }
        int k = lps[n - 1];
        return rev.substring(0, s.length() - k) + s;
    }
}

var shortestPalindrome = function(s) {
    const rev = s.split('').reverse().join('');
    const combo = s + '#' + rev;
    const n = combo.length;
    const lps = new Int32Array(n);
    let prev = 0, i = 1;
    while (i < n) {
        if (combo[i] === combo[prev]) {
            lps[i++] = ++prev;
        } else if (prev > 0) {
            prev = lps[prev - 1];
        } else {
            lps[i++] = 0;
        }
    }
    const k = lps[n - 1];
    return rev.slice(0, s.length - k) + s;
};
